import { readdirSync, readFileSync, statSync } from "node:fs";
import { basename, extname, join } from "node:path";

import type { AssertionResult } from "@dec-bench/eval-core";

const WORKSPACE_ROOT = "/workspace";
const IGNORED_DIRS = new Set([
  ".git",
  ".next",
  ".turbo",
  "dist",
  "build",
  "coverage",
  "node_modules",
  "__pycache__",
  ".venv",
  "venv",
]);
const TEXT_FILE_EXTENSIONS = new Set([
  ".py",
  ".js",
  ".jsx",
  ".ts",
  ".tsx",
  ".sql",
  ".sh",
  ".bash",
  ".zsh",
  ".rb",
  ".go",
  ".rs",
  ".java",
  ".yaml",
  ".yml",
  ".json",
  ".toml",
  ".ini",
  ".cfg",
  ".conf",
  ".md",
]);
const DOC_PATHS = [
  join(WORKSPACE_ROOT, "README.md"),
  join(WORKSPACE_ROOT, "README.txt"),
  join(WORKSPACE_ROOT, "docs"),
];
const DEFAULT_CONNECTION_LITERALS = [
  "localhost:5432",
  "localhost:8123",
  "localhost:9000",
  "localhost:9092",
];
const DEFAULT_ENV_TOKENS = [
  "process.env",
  "ctx.env(",
  "os.environ",
  "getenv(",
  "POSTGRES_URL",
  "CLICKHOUSE_URL",
  "REDPANDA_BROKER",
];

interface WorkspaceTextFile {
  path: string;
  relativePath: string;
  content: string;
}

export async function scanWorkspaceForHardcodedConnections(options?: {
  literals?: string[];
  envTokens?: string[];
}): Promise<AssertionResult> {
  const literals = options?.literals ?? DEFAULT_CONNECTION_LITERALS;
  const envTokens = options?.envTokens ?? DEFAULT_ENV_TOKENS;
  const findings: Array<{ file: string; line: number; literal: string }> = [];

  for (const file of collectWorkspaceTextFiles()) {
    const lines = file.content.split(/\r?\n/);
    for (let index = 0; index < lines.length; index += 1) {
      const line = lines[index] ?? "";
      if (!literals.some((literal) => line.includes(literal))) {
        continue;
      }
      if (envTokens.some((token) => line.includes(token))) {
        continue;
      }
      findings.push({
        file: file.relativePath,
        line: index + 1,
        literal: literals.find((literal) => line.includes(literal)) ?? "unknown",
      });
      if (findings.length >= 10) {
        break;
      }
    }
  }

  return {
    passed: findings.length === 0,
    message:
      findings.length === 0
        ? "No hardcoded connection strings found in workspace files."
        : "Hardcoded connection strings found in workspace files.",
    details: {
      findings,
    },
  };
}

export async function hasReadmeOrDocs(): Promise<AssertionResult> {
  const foundPaths = DOC_PATHS.filter((path) => exists(path));
  return {
    passed: foundPaths.length > 0,
    message:
      foundPaths.length > 0
        ? "Workspace includes operator-facing docs or a README."
        : "Workspace is missing a README or docs directory for operator handoff.",
    details: {
      foundPaths,
    },
  };
}

export async function avoidsSelectStarQueries(): Promise<AssertionResult> {
  const findings: Array<{ file: string; line: number }> = [];
  for (const file of collectWorkspaceTextFiles()) {
    const lines = file.content.split(/\r?\n/);
    for (let index = 0; index < lines.length; index += 1) {
      const line = lines[index] ?? "";
      if (!/\bselect\s+\*/i.test(line)) {
        continue;
      }
      findings.push({
        file: file.relativePath,
        line: index + 1,
      });
      if (findings.length >= 10) {
        break;
      }
    }
  }

  return {
    passed: findings.length === 0,
    message:
      findings.length === 0
        ? "Workspace avoids `SELECT *` queries in checked source files."
        : "Workspace still contains `SELECT *` queries in checked source files.",
    details: {
      findings,
    },
  };
}

function collectWorkspaceTextFiles(): WorkspaceTextFile[] {
  const files: WorkspaceTextFile[] = [];
  const visit = (current: string, relativePrefix = "") => {
    for (const entry of readdirSync(current, { withFileTypes: true })) {
      if (entry.isDirectory()) {
        if (IGNORED_DIRS.has(entry.name)) {
          continue;
        }
        visit(join(current, entry.name), join(relativePrefix, entry.name));
        continue;
      }
      if (!entry.isFile()) {
        continue;
      }
      const extension = extname(entry.name).toLowerCase();
      if (!TEXT_FILE_EXTENSIONS.has(extension) && basename(entry.name).toLowerCase() !== "dockerfile") {
        continue;
      }

      const absolutePath = join(current, entry.name);
      if (!isReadableTextFile(absolutePath)) {
        continue;
      }
      files.push({
        path: absolutePath,
        relativePath: join(relativePrefix, entry.name),
        content: readFileSync(absolutePath, "utf8"),
      });
    }
  };

  if (exists(WORKSPACE_ROOT)) {
    visit(WORKSPACE_ROOT);
  }
  return files;
}

function exists(path: string): boolean {
  try {
    return statSync(path).isFile() || statSync(path).isDirectory();
  } catch {
    return false;
  }
}

function isReadableTextFile(path: string): boolean {
  try {
    const stat = statSync(path);
    return stat.isFile() && stat.size <= 512_000;
  } catch {
    return false;
  }
}

#!/usr/bin/env python3
import os
import subprocess
import sys
import time
from urllib.parse import urlparse


TARGET_DB = "analytics"
TARGET_TABLE = "sales"
SOURCE_TABLE = "sales_pg_source"
SOURCE_SCHEMA = "app"
DEFAULT_INTERVAL_SECONDS = 2.0


def env_url(name: str) -> str:
    value = os.environ.get(name)
    if not value:
        raise RuntimeError(f"Missing required environment variable: {name}")
    return value


def shell(args: list[str], input_text: str | None = None) -> str:
    result = subprocess.run(
        args,
        input=input_text,
        text=True,
        capture_output=True,
        check=False,
    )
    if result.returncode != 0:
        raise RuntimeError(result.stderr.strip() or result.stdout.strip() or "command failed")
    return result.stdout.strip()


def clickhouse(query: str, multiquery: bool = False) -> str:
    args = ["clickhouse-client"]
    if multiquery:
      args.append("--multiquery")
    args.extend(["--query", query])
    return shell(args)


def sql_string(value: str) -> str:
    return "'" + value.replace("\\", "\\\\").replace("'", "\\'") + "'"


def pg_engine_clause() -> str:
    parsed = urlparse(env_url("POSTGRES_URL"))
    host = parsed.hostname or "localhost"
    port = parsed.port or 5432
    database = (parsed.path or "/postgres").lstrip("/") or "postgres"
    user = parsed.username or "postgres"
    password = parsed.password or ""
    return (
        f"PostgreSQL({sql_string(f'{host}:{port}')}, "
        f"{sql_string(database)}, "
        f"{sql_string('sales')}, "
        f"{sql_string(user)}, "
        f"{sql_string(password)}, "
        f"{sql_string(SOURCE_SCHEMA)})"
    )


def bootstrap() -> None:
    clickhouse(
        f"""
        CREATE DATABASE IF NOT EXISTS {TARGET_DB};
        DROP TABLE IF EXISTS {TARGET_DB}.{SOURCE_TABLE};
        DROP TABLE IF EXISTS {TARGET_DB}.{TARGET_TABLE};
        CREATE TABLE {TARGET_DB}.{SOURCE_TABLE}
        (
            id UInt32,
            product_id String,
            quantity Int32,
            amount Decimal(10, 2),
            sale_date Date
        )
        ENGINE = {pg_engine_clause()};
        CREATE TABLE {TARGET_DB}.{TARGET_TABLE}
        (
            id UInt32,
            product_id String,
            quantity Int32,
            amount Decimal(10, 2),
            sale_date Date
        )
        ENGINE = MergeTree()
        ORDER BY (sale_date, product_id, id);
        """,
        multiquery=True,
    )
    sync_once()


def ensure_bridge() -> None:
    clickhouse(
        f"""
        CREATE DATABASE IF NOT EXISTS {TARGET_DB};
        CREATE TABLE IF NOT EXISTS {TARGET_DB}.{TARGET_TABLE}
        (
            id UInt32,
            product_id String,
            quantity Int32,
            amount Decimal(10, 2),
            sale_date Date
        )
        ENGINE = MergeTree()
        ORDER BY (sale_date, product_id, id);
        DROP TABLE IF EXISTS {TARGET_DB}.{SOURCE_TABLE};
        CREATE TABLE {TARGET_DB}.{SOURCE_TABLE}
        (
            id UInt32,
            product_id String,
            quantity Int32,
            amount Decimal(10, 2),
            sale_date Date
        )
        ENGINE = {pg_engine_clause()};
        """,
        multiquery=True,
    )


def sync_once() -> None:
    clickhouse(
        f"""
        INSERT INTO {TARGET_DB}.{TARGET_TABLE} (id, product_id, quantity, amount, sale_date)
        SELECT
            id,
            product_id,
            quantity,
            amount,
            sale_date
        FROM {TARGET_DB}.{SOURCE_TABLE}
        WHERE id > (SELECT ifNull(max(id), toUInt32(0)) FROM {TARGET_DB}.{TARGET_TABLE})
        ORDER BY id
        """,
    )


def status() -> str:
    return clickhouse(
        f"""
        SELECT
            count() AS row_count,
            sum(amount) AS amount_sum,
            max(id) AS max_id
        FROM {TARGET_DB}.{TARGET_TABLE}
        FORMAT TSV
        """
    )


def daemon() -> None:
    ensure_bridge()
    interval = float(os.environ.get("SYNC_INTERVAL_SECONDS", str(DEFAULT_INTERVAL_SECONDS)))
    while True:
        try:
            sync_once()
            print(f"{time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime())}\t{status()}", flush=True)
        except Exception as exc:
            print(
                f"{time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime())}\terror\t{exc}",
                file=sys.stderr,
                flush=True,
            )
        time.sleep(interval)


def main() -> None:
    if len(sys.argv) != 2 or sys.argv[1] not in {"bootstrap", "sync-once", "daemon", "status"}:
        raise SystemExit("usage: sync_sales.py [bootstrap|sync-once|daemon|status]")

    command = sys.argv[1]
    if command == "bootstrap":
        bootstrap()
        print(status())
        return
    if command == "sync-once":
        ensure_bridge()
        sync_once()
        print(status())
        return
    if command == "status":
        print(status())
        return
    daemon()


if __name__ == "__main__":
    main()
